package dev.rodrigosambade.net;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.time.Duration;import java.util.*;import java.util.concurrent.ThreadLocalRandom;
public final class ConnectivityAndInternetAccess{private static final InetSocketAddress[]DNS={new InetSocketAddress("1.1.1.1",53),new InetSocketAddress("8.8.8.8",53)},TCP={new InetSocketAddress("1.1.1.1",443),new InetSocketAddress("8.8.8.8",443)};private ConnectivityAndInternetAccess(){}public record Result(boolean networkInterfaceAvailable,boolean internetReachable,String method,String endpoint){}public static boolean isLocalHost(String host){if(host==null||host.isBlank())return false;if(host.equalsIgnoreCase("localhost"))return true;try{InetAddress a=InetAddress.getByName(host);return a.isLoopbackAddress()||a.isAnyLocalAddress();}catch(IOException e){return false;}}public static boolean hasUsableNetworkInterface()throws SocketException{for(NetworkInterface n:Collections.list(NetworkInterface.getNetworkInterfaces())){if(!n.isUp()||n.isLoopback()||n.isVirtual())continue;if(Collections.list(n.getInetAddresses()).stream().anyMatch(a->!a.isLoopbackAddress()&&!a.isLinkLocalAddress()))return true;}return false;}public static Result check(Duration timeout){int ms=Math.toIntExact(Math.max(1,timeout.toMillis()));boolean iface;try{iface=hasUsableNetworkInterface();}catch(SocketException e){return new Result(false,false,"interface","enumeration-failed");}if(!iface)return new Result(false,false,"interface","none");for(var r:DNS)if(dnsProbe(r,ms))return new Result(true,true,"dns",r.toString());for(var e:TCP)if(tcpProbe(e,ms))return new Result(true,true,"tcp",e.toString());return new Result(true,false,"none","unreachable");}private static boolean dnsProbe(InetSocketAddress r,int ms){int id=ThreadLocalRandom.current().nextInt(0x10000);byte[]q;try{q=dnsQuery(id,"example.com");}catch(IOException e){return false;}byte[]b=new byte[512];try(DatagramSocket s=new DatagramSocket()){s.connect(r);s.setSoTimeout(ms);s.send(new DatagramPacket(q,q.length));DatagramPacket p=new DatagramPacket(b,b.length);s.receive(p);if(p.getLength()<12)return false;int rid=((b[0]&255)<<8)|(b[1]&255);return rid==id&&(b[2]&128)!=0&&(b[3]&15)==0;}catch(IOException e){return false;}}private static byte[]dnsQuery(int id,String h)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(DataOutputStream o=new DataOutputStream(bytes)){o.writeShort(id);o.writeShort(0x0100);o.writeShort(1);o.writeShort(0);o.writeShort(0);o.writeShort(0);for(String l:h.split("\\.")){byte[]e=l.getBytes(StandardCharsets.US_ASCII);o.writeByte(e.length);o.write(e);}o.writeByte(0);o.writeShort(1);o.writeShort(1);}return bytes.toByteArray();}private static boolean tcpProbe(InetSocketAddress e,int ms){try(Socket s=new Socket()){s.connect(e,ms);return true;}catch(IOException x){return false;}}public static void requireInternetForRemoteHost(String host,Duration timeout)throws IOException{if(isLocalHost(host))return;Result r=check(timeout);if(!r.internetReachable())throw new IOException("No usable Internet path detected for remote host "+host);}}
